<script setup lang="ts">import { computed,ref } from 'vue';import { useSystemStore } from '../stores/system';import Panel from '../components/Panel.vue';import StatusBadge from '../components/StatusBadge.vue';import ScoreBar from '../components/ScoreBar.vue';import { candidateBlacklistDto } from '../candidateBlacklistDto';import { RefreshCw } from 'lucide-vue-next';const s=useSystemStore(),tab=ref<'pool'|'universe'>('pool'),selected=ref<string|null>(null),rows=computed(()=>tab.value==='pool'?s.pool:s.universe.filter(x=>x.rank>0).slice(0,100)),candidate=computed(()=>s.universe.find(x=>x.symbol===selected.value));async function blacklistCandidate(scope:'SYMBOL'|'UNDERLYING'='SYMBOL'){const row=candidate.value;if(!row)return;await s.blacklistCandidate(candidateBlacklistDto(row,scope));selected.value=null;}</script>
<template><div class="page-stack"><div class="toolbar"><div class="segmented"><button :class="{active:tab==='pool'}" @click="tab='pool'">动态交易池</button><button :class="{active:tab==='universe'}" @click="tab='universe'">候选 Universe Top {{s.snapshot?.settings.selection.universeTopN}}</button></div><button class="button secondary" @click="s.refreshPool()"><RefreshCw :size="16"/>立即重排</button></div><Panel :title="tab==='pool'?'动态交易池':'候选 Universe'" subtitle="Market Quality 在 Ranking / Pool / Primary 前统一准入"><table class="data-table clickable"><thead><tr><th>#</th><th>Underlying</th><th>Contract</th><th>Tier</th><th>Quality</th><th>Spread</th><th>Location</th><th>状态</th></tr></thead><tbody><tr v-for="r in rows" :key="r.symbol" @click="selected=r.symbol" :class="{selected:selected===r.symbol}"><td>{{r.rank}}</td><td class="symbol">{{(r as any).underlyingAsset??r.symbol}}</td><td class="symbol">{{(r as any).selectedContract??r.symbol}}</td><td><StatusBadge :value="(r as any).riskTier??'LIQUID_ALT'"/></td><td><StatusBadge :value="(r as any).marketQuality?.grade??'—'"/></td><td>{{(r as any).marketQuality?.spreadBps?.toFixed?.(1)??'—'}} bps</td><td>{{(r as any).locationScore==null?'—':(r as any).locationScore}}</td><td><StatusBadge :value="(r as any).state??(r as any).lifecycle"/></td></tr></tbody></table></Panel><Panel title="候选画像" subtitle="质量、流动性与黑名单在 Primary 前完成"><template v-if="candidate"><div class="candidate-head"><div><span class="eyebrow">RANK #{{candidate.rank}}</span><h3>{{candidate.symbol}}</h3><p>Underlying {{(candidate as any).underlyingAsset??'—'}} · Quote {{(candidate as any).quoteAsset??'—'}}</p></div><div class="score-circle">{{candidate.score.toFixed(0)}}</div></div><div class="facts wide"><div><dt>Risk Tier</dt><dd>{{(candidate as any).riskTier??'—'}}</dd></div><div><dt>Market Quality</dt><dd>{{(candidate as any).marketQuality?.grade??'—'}}</dd></div><div><dt>Spread / 0.5% Depth</dt><dd>{{(candidate as any).marketQuality?.spreadBps?.toFixed?.(2)??'—'}} / {{Math.min((candidate as any).marketQuality?.bidDepth05Usd??0,(candidate as any).marketQuality?.askDepth05Usd??0).toFixed(0)}}</dd></div><div><dt>Listing Age</dt><dd>{{(candidate as any).marketQuality?.listingAgeDays?.toFixed?.(0)??'—'}}d</dd></div><div><dt>15m Realized Vol</dt><dd>{{(candidate as any).marketQuality?.realizedVolatility15mPct?.toFixed?.(2)??'—'}}%</dd></div><div><dt>质量原因</dt><dd>{{((candidate as any).marketQuality?.reasons??[]).join(' · ')||'PASS'}}</dd></div></div><ScoreBar label="主流流动性" :value="candidate.components.liquidity"/><ScoreBar label="执行可达性" :value="candidate.components.executionReachability"/><ScoreBar label="数据质量" :value="candidate.components.dataQuality"/><div class="toolbar"><RouterLink class="button primary" :to="`/intelligence?symbol=${candidate.symbol}`">打开专业证据包</RouterLink><button class="button secondary" @click="blacklistCandidate('SYMBOL')">Symbol 黑名单</button><button class="button secondary" @click="blacklistCandidate('UNDERLYING')">Underlying 黑名单</button></div></template><div v-else class="empty">点击任一候选查看组合策略画像</div></Panel></div></template>
